css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 9px 14px; margin-bottom: 13px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 6px;}
.mz .recuerda-cuerpo{font-size: 16px; line-height: 1.7;}
.mz .recuerda-cuerpo b{font-size: 18px;}
.mz .ej-block:last-of-type{margin-bottom: 0;}
.mz .mosaico{display: flex; gap: 14px; flex-wrap: wrap;}
.mz .mosaico .mn{font-size: 21px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 16px;}
.mz .pi-tabla{border-collapse: collapse; width: 100%;}
.mz .pi-tabla th,.mz .pi-tabla td{border: 1.5px solid var(--bosque);}
.mz .pi-tabla th{font-family: sans-serif; font-size: 13px; background: #f3f3f3; padding: 5px 0; width: 50%;}
.mz .pi-tabla td{height: 64px; vertical-align: top;}
.mz .serie-cajas{display: flex; gap: 8px; flex-wrap: wrap; font-size: 19px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 54px; height: 40px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .serie-label{font-size: 13px; font-weight: 600; font-family: sans-serif; margin-bottom: 5px;}
.mz .clasif{display: flex; gap: 14px; flex-wrap: wrap;}
.mz .clasif .item{display: flex; flex-direction: column; align-items: center; gap: 6px;}
.mz .clasif .item .cnum{font-size: 21px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 16px;}
.mz .clasif .item .cresp{width: 100%; height: 30px; border: 1.5px solid var(--bosque); border-radius: 6px;}
